custom_css:
/* ✦ Терновая ночь ✦ — тема для Tavo (нужен Advanced Rendering) */

@font-face {
  font-family: "Literata";
  font-style: normal;
  font-weight: 400 600;
  font-display: swap;
  src: url("theme/assets/literata-cyrillic.woff2") format("woff2");
  unicode-range: U+0301, U+0400-045F, U+0490-0491, U+04B0-04B1, U+2116;
}
@font-face {
  font-family: "Literata";
  font-style: normal;
  font-weight: 400 600;
  font-display: swap;
  src: url("theme/assets/literata-latin.woff2") format("woff2");
  unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;
}

@keyframes thorn-twinkle {
  0%, 100% { opacity: 0.45; }
  50% { opacity: 1; }
}

/* ── текст ── */
.tavo-bubble-content {
  font-family: "Literata", "Noto Serif", Georgia, serif;
  line-height: 1.78;
  letter-spacing: 0.005em;
}

.tavo-message-content ::selection {
  background: rgba(108, 127, 166, 0.45);
  color: #f2f5fb;
}

/* ── сообщения: тихие страницы на фоне неба ── */
.tavo-bubble {
  border: 1px solid rgba(142, 152, 168, 0.12);
  box-shadow: inset 0 0 36px rgba(3, 6, 15, 0.35);
}

.tavo-character-bubble {
  border-left: 2px solid rgba(195, 202, 214, 0.32);
}

.tavo-user-bubble {
  border-left: 2px dashed rgba(142, 152, 168, 0.28);
}

/* разделитель: засохшая лоза с глазом */
.tavo-message-divider {
  height: 30px;
  border: 0;
  background: url("theme/assets/divider.svg") center / min(320px, 72%) auto no-repeat;
  opacity: 0.85;
}

/* ── имена и аватары ── */
.tavo-speaker-name {
  font-family: "Literata", Georgia, serif;
  letter-spacing: 0.12em;
  color: #aab3c2;
}

.tavo-speaker-name::before {
  content: "✦ ";
  color: #c3cad6;
  animation: thorn-twinkle 4.5s ease-in-out infinite;
}

.tavo-avatar {
  box-shadow: 0 0 0 1.5px rgba(195, 202, 214, 0.5), 0 0 14px rgba(159, 178, 214, 0.22);
}

/* ── размышления модели ── */
.tavo-message-reasoning {
  background: rgba(8, 14, 30, 0.6);
  border: 1px dashed rgba(142, 152, 168, 0.35);
  border-radius: 12px;
  padding: 6px 12px;
  color: #8e98a8;
  font-size: 0.9em;
}

.tavo-message-reasoning > summary {
  color: #aab3c2;
  letter-spacing: 0.06em;
  opacity: 0.85;
}

/* спойлеры <details> внутри ответов (архив отношений и т.п.) */
.tavo-message-content details {
  margin: 8px 0;
  padding: 4px 12px;
  background: rgba(8, 14, 30, 0.45);
  border: 1px solid rgba(142, 152, 168, 0.25);
  border-radius: 10px;
  font-size: 0.88em;
}

.tavo-message-content details > summary {
  color: #aab3c2;
  cursor: pointer;
}

.tavo-message-content hr {
  border: 0;
  height: 30px;
  background: url("theme/assets/divider.svg") center / min(260px, 60%) auto no-repeat;
  opacity: 0.7;
}

/* ── кнопки под сообщением ── */
.tavo-action-bar-button {
  opacity: 0.7;
}

/* ── поле ввода ── */
.tavo-composer-shell {
  background: linear-gradient(180deg, rgba(14, 22, 44, 0.88), rgba(8, 13, 28, 0.92));
  border: 1px solid rgba(195, 202, 214, 0.22);
  border-radius: 22px;
  box-shadow: 0 -4px 24px rgba(3, 6, 15, 0.55), inset 0 1px 0 rgba(195, 202, 214, 0.08);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
}

.tavo-composer-input {
  color: #e6ebf3;
  caret-color: #c3cad6;
  font-family: "Literata", Georgia, serif;
}

.tavo-composer-send-icon,
.tavo-composer-add-icon,
.tavo-composer-voice-icon,
.tavo-composer-stop-icon {
  filter: grayscale(1) brightness(1.5);
  opacity: 0.85;
}
